1	import React, { useEffect, useState } from 'react';
2	
3	// An opened invoice's line items, rendered inside the projects feature. The owner lists the things
4	// being charged for — each with a description, how many, and the price each — and the invoice total
5	// is worked out for them (the sum of each line's quantity times unit price). Owns its own state and
6	// data loading (no global store); composed, not branched.
7	type LineItem = {
8	  id: number;
9	  invoiceId: number;
10	  description: string;
11	  quantity: number;
12	  unitPrice: number;
13	};
14	
15	function formatAmount(amount: number): string {
16	  return `$${Number(amount).toLocaleString('en-US', {
17	    minimumFractionDigits: 2,
18	    maximumFractionDigits: 2,
19	  })}`;
20	}
21	
22	export function InvoiceLineItems({
23	  invoiceId,
24	  onClose,
25	}: {
26	  invoiceId: number;
27	  onClose: () => void;
28	}) {
29	  const [lineItems, setLineItems] = useState<LineItem[]>([]);
30	  const [description, setDescription] = useState('');
31	  const [qty, setQty] = useState('');
32	  const [unitPrice, setUnitPrice] = useState('');
33	  const [error, setError] = useState('');
34	  const [editingId, setEditingId] = useState<number | null>(null);
35	  const [editDescription, setEditDescription] = useState('');
36	  const [editQty, setEditQty] = useState('');
37	  const [editUnitPrice, setEditUnitPrice] = useState('');
38	  const [editError, setEditError] = useState('');
39	
40	  async function load() {
41	    const res = await fetch(`/api/invoices/${invoiceId}/lineitems`);
42	    setLineItems(await res.json());
43	  }
44	
45	  useEffect(() => {
46	    void load();
47	  }, [invoiceId]);
48	
49	  async function onSubmit(e: React.FormEvent) {
50	    e.preventDefault();
51	    const quantity = Number(qty);
52	    const price = Number(unitPrice);
53	    if (!description.trim() || !(quantity > 0) || !(price >= 0)) {
54	      setError('A description, a quantity and a price are required');
55	      return;
56	    }
57	    setError('');
58	    const res = await fetch(`/api/invoices/${invoiceId}/lineitems`, {
59	      method: 'POST',
60	      headers: { 'Content-Type': 'application/json' },
61	      body: JSON.stringify({ description, quantity, unitPrice: price }),
62	    });
63	    if (!res.ok) {
64	      return;
65	    }
66	    setDescription('');
67	    setQty('');
68	    setUnitPrice('');
69	    await load();
70	  }
71	
72	  function startEdit(li: LineItem) {
73	    setEditingId(li.id);
74	    setEditDescription(li.description);
75	    setEditQty(String(li.quantity));
76	    setEditUnitPrice(String(li.unitPrice));
77	    setEditError('');
78	  }
79	
80	  function cancelEdit() {
81	    setEditingId(null);
82	    setEditError('');
83	  }
84	
85	  async function saveEdit(lineItemId: number) {
86	    const quantity = Number(editQty);
87	    const price = Number(editUnitPrice);
88	    if (!editDescription.trim() || !(quantity > 0) || !(price >= 0)) {
89	      setEditError('A description, a quantity and a price are required');
90	      return;
91	    }
92	    setEditError('');
93	    const res = await fetch(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, {
94	      method: 'PUT',
95	      headers: { 'Content-Type': 'application/json' },
96	      body: JSON.stringify({ description: editDescription, quantity, unitPrice: price }),
97	    });
98	    if (!res.ok) {
99	      return;
100	    }
101	    setEditingId(null);
102	    await load();
103	  }
104	
105	  async function remove(lineItemId: number) {
106	    const res = await fetch(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, {
107	      method: 'DELETE',
108	    });
109	    if (!res.ok) {
110	      return;
111	    }
112	    if (editingId === lineItemId) {
113	      setEditingId(null);
114	    }
115	    await load();
116	  }
117	
118	  const total = lineItems.reduce((sum, li) => sum + Number(li.quantity) * Number(li.unitPrice), 0);
119	
120	  return (
121	    <section data-testid="invoice-lineitems">
122	      <h2>Invoice line items</h2>
123	
124	      <button type="button" data-testid="invoice-close" onClick={onClose}>
125	        Back to invoices
126	      </button>
127	
128	      <form data-testid="lineitem-form" onSubmit={onSubmit}>
129	        <input
130	          data-testid="lineitem-form-description"
131	          placeholder="Description"
132	          value={description}
133	          onChange={(e) => setDescription(e.target.value)}
134	        />
135	        <input
136	          data-testid="lineitem-form-qty"
137	          placeholder="How many"
138	          value={qty}
139	          onChange={(e) => setQty(e.target.value)}
140	        />
141	        <input
142	          data-testid="lineitem-form-unitprice"
143	          placeholder="Price each"
144	          value={unitPrice}
145	          onChange={(e) => setUnitPrice(e.target.value)}
146	        />
147	        <button type="submit" data-testid="lineitem-form-submit">
148	          Add line item
149	        </button>
150	        {error ? (
151	          <p data-testid="lineitem-form-error" role="alert">
152	            {error}
153	          </p>
154	        ) : null}
155	      </form>
156	
157	      <table data-testid="invoice-lineitems-table">
158	        <thead>
159	          <tr>
160	            <th>Description</th>
161	            <th>How many</th>
162	            <th>Price each</th>
163	            <th>Line total</th>
164	            <th></th>
165	          </tr>
166	        </thead>
167	        <tbody>
168	          {lineItems.map((li) =>
169	            editingId === li.id ? (
170	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
171	                <td>
172	                  <input
173	                    data-testid="lineitem-edit-description"
174	                    placeholder="Description"
175	                    value={editDescription}
176	                    onChange={(e) => setEditDescription(e.target.value)}
177	                  />
178	                </td>
179	                <td>
180	                  <input
181	                    data-testid="lineitem-edit-qty"
182	                    placeholder="How many"
183	                    value={editQty}
184	                    onChange={(e) => setEditQty(e.target.value)}
185	                  />
186	                </td>
187	                <td>
188	                  <input
189	                    data-testid="lineitem-edit-unitprice"
190	                    placeholder="Price each"
191	                    value={editUnitPrice}
192	                    onChange={(e) => setEditUnitPrice(e.target.value)}
193	                  />
194	                </td>
195	                <td data-testid="lineitem-total">
196	                  {formatAmount(Number(editQty || 0) * Number(editUnitPrice || 0))}
197	                </td>
198	                <td>
199	                  <button
200	                    type="button"
201	                    data-testid={`lineitem-save-${li.id}`}
202	                    onClick={() => void saveEdit(li.id)}
203	                  >
204	                    Save
205	                  </button>
206	                  <button
207	                    type="button"
208	                    data-testid={`lineitem-cancel-${li.id}`}
209	                    onClick={cancelEdit}
210	                  >
211	                    Cancel
212	                  </button>
213	                  {editError ? (
214	                    <p data-testid="lineitem-edit-error" role="alert">
215	                      {editError}
216	                    </p>
217	                  ) : null}
218	                </td>
219	              </tr>
220	            ) : (
221	              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
222	                <td data-testid="lineitem-description">{li.description}</td>
223	                <td data-testid="lineitem-qty">{li.quantity}</td>
224	                <td data-testid="lineitem-unitprice">{formatAmount(li.unitPrice)}</td>
225	                <td data-testid="lineitem-total">
226	                  {formatAmount(Number(li.quantity) * Number(li.unitPrice))}
227	                </td>
228	                <td>
229	                  <button
230	                    type="button"
231	                    data-testid={`lineitem-edit-${li.id}`}
232	                    onClick={() => startEdit(li)}
233	                  >
